WITH TIPO_PESO_CORRETO AS ( SELECT V.CODPARC, TA.TIPO_PESO FROM VINCULO_PARCEIRO_TIPO V JOIN TIPO_ARMAZENAGEM TA ON V.ID_TIPO_ARMAZENAGEM = TA.ID WHERE V.CODPARC = :VAR_PARCEIRO_SELECIONADO ORDER BY V.ID DESC LIMIT 1 ), SALDO_ANTERIOR_PRODUTO AS ( SELECT DESCRPROD, SUM(CASE WHEN TIPO_MOV = 'ENTRADA' THEN PESO ELSE -PESO END) AS SALDO_PESO, SUM(CASE WHEN TIPO_MOV = 'ENTRADA' THEN VALOR ELSE -VALOR END) AS SALDO_VALOR FROM ( SELECT I.DESCRPROD, (CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN I.PESO_ITEM_LIQ ELSE I.PESO_ITEM END) AS PESO, (I.VLRUNIT * I.QTDNEG) AS VALOR, 'ENTRADA' AS TIPO_MOV FROM (SELECT * FROM GESTAO_NOTAS_APROVACAO UNION ALL SELECT * FROM NOTA_ARMAZ_APROVAR_ESPELHO) G JOIN IMP_ITENS_NOTAS_APRV I ON G.NUNOTA = I.NUNOTA JOIN TIPO_PESO_CORRETO TPC ON G.CODPARC = TPC.CODPARC WHERE G.CODPARC = :VAR_PARCEIRO_SELECIONADO AND G.ENTREGUE = 1 AND G.DATA_ENTREGA < :VAR_PERIODO_INICIO UNION ALL SELECT N.DESCRPROD, (CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN N.PESO_ITEM_LIQ ELSE N.PESO_ITEM END) AS PESO, (N.VLRUNIT * N.QTDNEG) AS VALOR, 'SAIDA' AS TIPO_MOV FROM IMP_NOTAS_ARMAZ N JOIN TIPO_PESO_CORRETO TPC ON N.CODPARC = TPC.CODPARC WHERE N.CODPARC = :VAR_PARCEIRO_SELECIONADO AND N.ATUALESTOQUE = 1 AND N.DTNEG < :VAR_PERIODO_INICIO ) AS HIST GROUP BY DESCRPROD ), MOVIMENTOS_PERIODO AS ( SELECT DESCRPROD, SUM(CASE WHEN TIPO_MOV = 'ENTRADA' THEN PESO ELSE 0 END) AS ENTRADA_PESO, SUM(CASE WHEN TIPO_MOV = 'SAIDA' THEN PESO ELSE 0 END) AS SAIDA_PESO, SUM(CASE WHEN TIPO_MOV = 'ENTRADA' THEN VALOR ELSE 0 END) AS ENTRADA_VALOR, SUM(CASE WHEN TIPO_MOV = 'SAIDA' THEN VALOR ELSE 0 END) AS SAIDA_VALOR FROM ( SELECT I.DESCRPROD, (CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN I.PESO_ITEM_LIQ ELSE I.PESO_ITEM END) AS PESO, (I.VLRUNIT * I.QTDNEG) AS VALOR, 'ENTRADA' AS TIPO_MOV FROM (SELECT * FROM GESTAO_NOTAS_APROVACAO UNION ALL SELECT * FROM NOTA_ARMAZ_APROVAR_ESPELHO) G JOIN IMP_ITENS_NOTAS_APRV I ON G.NUNOTA = I.NUNOTA JOIN TIPO_PESO_CORRETO TPC ON G.CODPARC = TPC.CODPARC WHERE G.CODPARC = :VAR_PARCEIRO_SELECIONADO AND G.ENTREGUE = 1 AND G.DATA_ENTREGA BETWEEN :VAR_PERIODO_INICIO AND :VAR_PERIODO_FIM UNION ALL SELECT N.DESCRPROD, (CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN N.PESO_ITEM_LIQ ELSE N.PESO_ITEM END) AS PESO, (N.VLRUNIT * N.QTDNEG) AS VALOR, 'SAIDA' AS TIPO_MOV FROM IMP_NOTAS_ARMAZ N JOIN TIPO_PESO_CORRETO TPC ON N.CODPARC = TPC.CODPARC WHERE N.CODPARC = :VAR_PARCEIRO_SELECIONADO AND N.ATUALESTOQUE = 1 AND N.DTNEG BETWEEN :VAR_PERIODO_INICIO AND :VAR_PERIODO_FIM ) AS PERIODO GROUP BY DESCRPROD ), PRODUTOS_TOTAIS AS ( SELECT DESCRPROD FROM SALDO_ANTERIOR_PRODUTO UNION SELECT DESCRPROD FROM MOVIMENTOS_PERIODO ) SELECT P.DESCRPROD AS PRODUTO, IFNULL(M.ENTRADA_PESO, 0) AS QTD_ENTRADA, IFNULL(M.SAIDA_PESO, 0) AS QTD_SAIDA, IFNULL(M.ENTRADA_PESO, 0) - IFNULL(M.SAIDA_PESO, 0) AS SALDO_LIQUIDO, GREATEST(IFNULL(S.SALDO_PESO, 0) + IFNULL(M.ENTRADA_PESO, 0) - IFNULL(M.SAIDA_PESO, 0), 0) AS SALDO_REAL, IFNULL(S.SALDO_VALOR, 0) + IFNULL(M.ENTRADA_VALOR, 0) - IFNULL(M.SAIDA_VALOR, 0) AS VALOR_TOTAL FROM PRODUTOS_TOTAIS P LEFT JOIN MOVIMENTOS_PERIODO M ON P.DESCRPROD = M.DESCRPROD LEFT JOIN SALDO_ANTERIOR_PRODUTO S ON P.DESCRPROD = S.DESCRPROD HAVING QTD_ENTRADA > 0 OR QTD_SAIDA > 0 OR SALDO_REAL > 0.01 ORDER BY SALDO_LIQUIDO DESC, SALDO_REAL DESC